    {"|", "</td></tr></table>"},
    {"---", "<hr>"},
    {"\\n", "<br>"}
};

// Escape special characters in HTML
std::string escape_html(const std::string& input) {
    std::string result;
    for (char c : input) {
        switch (c) {
            case '&':
                result += "&amp;";
                break;
            case '<':
                result += "&lt;";
                break;
            case '>':
                result += "&gt;";
                break;
            case '"':
                result += "&quot;";
                break;
            default:
                result += c;
                break;
        }
    }
    return result;
}

std::string markdown_to_html(const std::string& markdown) {
    std::string html;

    // Split Markdown into lines
    std::vector<std::string> lines;
    std::string line;
    std::istringstream iss(markdown);
    while (std::getline(iss, line, '\n')) {
        lines.push_back(line);
    }

    // Convert each line of Markdown to HTML
    for (const auto& line : lines) {
        // Split line into tokens
        std::vector<std::string> tokens;
        std::string token;
        std::stringstream ss(line);
        while (std::getline(ss, token, ' ')) {
            tokens.push_back(token);
        }

        bool inside_code_block = false;
        bool inside_table_cell = false;

        // Convert each token to HTML
        for (const auto& token : tokens) {
            std::string html_token;

            // Check if token is a Markdown syntax
            auto it = MARKDOWN_TO_HTML.find(token);
            if (it != MARKDOWN_TO_HTML.end()) {
                html_token = it->second;

                // If inside a code block, escape HTML tags
                if (inside_code_block) {
                    html_token = escape_html(html_token);
                }
                // If inside a table cell, wrap with `<td>` and `</td>`
                else if (inside_table_cell) {
                    html_token = "<td>" + html_token + "</td>";
                }
            }
            // Otherwise, just escape HTML special characters
            else {
                html_token = escape_html(token);
            }

            // Handle nested syntax
            if (token == "`") {
                inside_code_block = !inside_code_block;
            }
            else if (token == "|") {
                if (inside_table_cell) {
                    html_token += "</td><td>";
                }
                else {
                    html_token = "<table><tr>" + html_token + "</tr>";
                    inside_table_cell = true;
                }
            }
            else if (token == "||") {
                if (inside_table_cell) {
                    html_token += "</td></tr></table>";
                    inside_table_cell = false;
                }
            }

            html += html_token;
        }
        html += "\n";
    }

    return html;
}
```

